  [437311] = { "召喚のポータルを作り出す儀式を始めます。召喚のポータルは、パーティーまたはレイドのメンバー2人が使って、指定したパーティーまたはレイドのメンバーを召喚できます。儀式のポータルを完成させるには、術者と追加のパーティーまたはレイドのメンバー2人が必要です。参加するには、全員が戦闘中でない状態でポータルを右クリックし、儀式が完了するまで動かないでください。", nil, 0xc8e21a4f, nil, "um" },
  [437324] = { "眠りの雲に触れた対象は$D1の間眠りに落ち、受けるダメージと受ける治癒が$N2%減少します。", "スタンしています。\n受けるダメージが$N1%減少します。\n受ける回復量が$N2%減少します。", 0x6f67d095, 0xb910554a, "uu" },
  [437327] = { "周囲の空気に潜む秘術のエネルギーを利用して閃きを得て、$D1の間、すべての呪文のマナコストを$N1%減少させ、与えるダメージと回復量を最大$N2増加させます。", "充填されたひらめきを得ました。すべての呪文のマナコストが減少し、呪文の威力が上昇しています。", 0x24c5eb1b, 0xf61c90bd, "uu" },
  [437340] = { "このヘルメットの放射線緩和プロトコルを起動し、有効な毒の効果をすべて即座に解除して、$D1の間、すべてのNatureダメージに対して無敵になります。", "Natureダメージに対する免疫があります。", 0x4ebeb267, 0x68bd12e9, "uu" },
  [437349] = { "ノーム神経的なショックを与え、自分に即座に$N1のダメージを与えますが、$D1の間、近接攻撃と遠隔攻撃の攻撃速度が$N2%上昇します。", "攻撃速度が上昇しています。", 0xef371b03, 0x13f57478, "uu" },
  [437353] = { "術者が対象に腐食性の魔法の波を吐きかけ、$N1のNatureダメージを与え、$D1の間アーマーを$N2%低下させます。", "アーマーが$N1%低下しています。", 0x2858ba79, 0x7bc85918, "uu" },
  [437357] = { "ノームマンシーの瞑想状態になり、詠唱中もマナの回復の$N1%が続くようになり、$D1の間、呪文による与えるダメージと回復量が最大$N2増加します。", "呪文の威力が上昇し、詠唱中にマナを獲得しています。", 0x86098cef, 0x03b0eb0f, "uu" },
  [437362] = { "超伝導ショックを与え、自分に即座に$N1のダメージを与えますが、$D1の間、呪文の詠唱速度が$N2%上昇します。", "詠唱速度が上昇しています。", 0x8d58fca5, 0x18ca25de, "uu" },
  [437367] = { "ブロックに成功すると、この盾の回転する鋭い歯車が、攻撃者に$N1の物理ダメージを、所持者に$N2の物理ダメージを与えます。", nil, 0x725e04a5, nil, "um" },
  [437368] = { "ベルトから超伝導コインを取り出して弾きます。表：$D1の間、すべての呪文と攻撃のクリティカル率が$N1%上昇します。裏：$D2の間、移動速度が$N3%上昇します。", nil, 0xc6aaecf9, nil, "um" },
  [437375] = { "術者の背後にいる対象に$N1のダメージを与え、吹き飛ばします。", nil, 0x16a70bcb, nil, "um" },
